# LAI-AQS-027 (ADR-052): batch statuses are renamed to the queue's vocabulary, and a batch that
# was RUNNING on a background thread gets the lease the old 15-minute stale rule implied, so a
# worker can take it over. Both steps are reversible.
RENAMES = {"COMPLETED": "SUCCEEDED", "PARTIAL": "PARTIALLY_FAILED"}
LEGACY_STALE = datetime.timedelta(minutes=15)


