    now = django.utils.timezone.now()
    for batch in batches.objects.filter(status="RUNNING", lease_expires_at__isnull=True):
        batch.lease_owner = "legacy-thread"
        batch.lease_expires_at = (batch.started_at or now) + LEGACY_STALE
        batch.save(update_fields=["lease_owner", "lease_expires_at"])


